# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


# ---
def gaps_for(worked, opening):
    return find_gaps([parse_span(text) for text in worked], parse_span(opening))


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = gaps_for(["09:00-12:00", "13:00-17:00"], "09:00-17:00")
        self.assertEqual(result, ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        result = gaps_for(["10:00-11:00"], "09:00-12:30")
        self.assertEqual(
            result,
            ["gap 09:00-10:00 (60 min)", "gap 11:00-12:30 (90 min)"]
        )

    def test_overlapping_and_touching_spans_leave_no_gap(self):
        worked = ["09:00-13:00", "12:00-15:00", "15:00-17:00"]
        self.assertEqual(gaps_for(worked, "09:00-17:00"), [])

    def test_nobody_working_is_one_big_gap(self):
        result = gaps_for([], "09:00-17:00")
        self.assertEqual(result, ["gap 09:00-17:00 (480 min)"])

    def test_unsorted_input(self):
        result = gaps_for(["14:00-17:00", "09:00-12:00"], "09:00-17:00")
        self.assertEqual(result, ["gap 12:00-14:00 (120 min)"])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            gaps_for(["08:00-10:00"], "09:00-17:00")

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gaps_for(["16:00-18:00"], "09:00-17:00")


if __name__ == "__main__":
    unittest.main()
